38	     */
39	    public int write(byte[] data) throws IOException, JSONException {
40	        int result = 1;
41	        URL baseURL = new URL("http://" + baseIP + "/" + sendDataEndPoint);
42	        int written = 0;
43	        JSONArray responseArray = new JSONArray();
44	        while (written < data.length) {
45	            JSONObject jsonObject = new JSONObject();
46	            jsonObject.put(dataKeyString, data[written]);
47	            RequestBody body = RequestBody.create(jsonObject.toString(), MediaType.get("application/json; charset=utf-8"));
48	            Request request = new Request.Builder()
49	                    .url(baseURL)
50	                    .post(body)
51	                    .build();
52	            Response response = client.newCall(request).execute();
53	            responseArray.put(new JSONObject(response.body().string()));
54	            if (response.code() != 200) {
55	                Log.e(TAG, "Error writing byte:" + written);
56	                return 0;
57	            }
58	            written++;
59	        }
60	        receivedData = new JSONObject(responseArray.toString());
