import okhttp3.HttpUrl;
import okhttp3.Request;

public class Verify {
    // mirrors ESPFragment.isValidHost
    static boolean isValidHost(String host) {
        return host != null && !host.isEmpty() && HttpUrl.parse("http://" + host) != null;
    }

    public static void main(String[] args) {
        String[] inputs = {".lo", "", "   ", "192.168.4.1", "esp.local", "1.2.3.4:8080",
                           "http://", "a b", "[", "..", "-", "%%%"};
        for (String in : inputs) {
            String trimmed = in.trim();
            boolean valid = isValidHost(trimmed);

            // Would the OLD code have crashed on this input?
            String old;
            try {
                new Request.Builder().url("http://" + trimmed).build();
                old = "ok";
            } catch (IllegalArgumentException e) {
                old = "CRASH(IllegalArgumentException)";
            }

            // NEW code path: only builds a request when valid
            String now;
            try {
                if (valid) { new Request.Builder().url(HttpUrl.parse("http://" + trimmed)).build(); now = "request built"; }
                else { now = "snackbar: invalid IP"; }
            } catch (RuntimeException e) {
                now = "CRASH(" + e.getClass().getSimpleName() + ")";
            }

            System.out.printf("%-14s valid=%-5s old=%-32s new=%s%n", "\"" + in + "\"", valid, old, now);
        }
    }
}
