                        .build();
                Response response = client.newCall(request).execute();
                if (response.code() == 200) {
                    ScienceLabCommon.setIsWifiConnected(true);
                    ScienceLabCommon.setEspBaseIP(espIPAddress);
                }
                result = response.body().string();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return result;
